function transform(data) {
  const rows = Array.isArray(data) ? [...data] : [];

  const iconFor = (title) => {
    const t = (title || "").toLowerCase();
    if (t.includes("home")) return "home";
    if (t.includes("shift")) return "calendar";
    return "circle";
  };

  // Your desired order (after Home)
  const ORDER = [
    "Shifts",
    // "Timesheets",
    // "Messages",
    // "Settings",
  ];

  const rank = (title) => {
    if (title === "Home") return -1000;              // always first
    const i = ORDER.indexOf(title);
    if (i !== -1) return i;                          // custom order next
    return 1000;                                     // everything else after
  };

  rows.sort((a, b) => {
    const at = a.page_title || "";
    const bt = b.page_title || "";

    const ra = rank(at);
    const rb = rank(bt);
    if (ra !== rb) return ra - rb;

    // tie-break: alphabetic
    return at.localeCompare(bt);
  });

  return rows.map(r => ({
    label: r.page_title,
    route: "/mobile" + r.route,
    icon: iconFor(r.page_title)
  }));
}

function transform(data) {
  const toOptionArray = (optionsText) =>
    String(optionsText || "")
      .split("\n")
      .map((s) => s.trim())
      .filter(Boolean)
      .map((label) => ({
        label,
        value: label
          .toLowerCase()
          .replace(/&/g, " and ")
          .replace(/[^a-z0-9]+/g, "-")
          .replace(/^-+|-+$/g, ""),
      }));

  const toBoolean = (v) => {
    if (v === true || v === false) return v;
    if (v === 1 || v === "1") return true;
    if (v === 0 || v === "0") return false;
    if (typeof v === "string") {
      const s = v.trim().toLowerCase();
      if (s === "true") return true;
      if (s === "false") return false;
    }
    return false;
  };

  const toIntBool = (v) => (toBoolean(v) ? 1 : 0);

  const extractParentFromDependsOn = (dependsOn) => {
    if (typeof dependsOn !== "string" || !dependsOn.trim()) return null;
    const m = dependsOn.match(/\bdoc\.([a-zA-Z_][a-zA-Z0-9_]*)\b/);
    return m ? m[1] : null;
  };

  if (!data || !Array.isArray(data.docs)) return data;

  // Shared visibility state across fields/components
  globalThis.__switchState = globalThis.__switchState || {};

  return {
    ...data,
    docs: data.docs.map((doc) => {
      if (!doc || !Array.isArray(doc.fields)) return doc;

      // First pass: normalize fields + capture values by fieldname
      const byFieldname = {};
      const normalizedFields = doc.fields.map((field) => {
        const fieldtype = (field?.fieldtype || "").toLowerCase();
        const out = { ...field };

        // Always set parent_link explicitly (string or null)
        out.parent_link = extractParentFromDependsOn(field?.depends_on);

        // Select: newline options -> [{label,value}]
        if (fieldtype === "select" && typeof field?.options === "string") {
          out.options = toOptionArray(field.options);
        }

        // Check: normalize booleans
        if (fieldtype === "check") {
          out.default = toBoolean(field.default);

          if (Object.prototype.hasOwnProperty.call(field, "modelValue")) {
            out.modelValue = toBoolean(field.modelValue);
          } else {
            // ensure modelValue exists for stable UI bindings
            out.modelValue = out.default;
          }
        }

        // Build lookup (prefer modelValue for checks)
        if (out?.fieldname) {
          if (fieldtype === "check") {
            byFieldname[out.fieldname] = toIntBool(
              out.modelValue !== undefined ? out.modelValue : out.default
            );
          } else {
            byFieldname[out.fieldname] =
              out?.value !== undefined ? out.value : out?.default;
          }
        }

        return out;
      });

      // Second pass: set parent_value using byFieldname
      const transformedFields = normalizedFields.map((field) => {
        const out = { ...field };

        if (out.parent_link) {
          out.parent_value = toIntBool(byFieldname[out.parent_link]);
        } else {
          out.parent_value = null;
        }

        // Seed global switch state for visibility logic
        if ((out?.fieldtype || "").toLowerCase() === "check" && out.fieldname) {
          globalThis.__switchState[out.fieldname] = toIntBool(
            out.modelValue !== undefined ? out.modelValue : out.default
          );
        }

        return out;
      });

      return {
        ...doc,
        fields: transformedFields,
      };
    }),
  };
}
